// #a8e7e24c31c0c182cdc6043e — готовый отчёт, по которому уже принято решение, не попадает в набор ссылки
// «לכל הדוחות המוכנים» (status=awaiting_decision), но остаётся в «מוכן». Кейс DASH-002.
// QA-данные: QA-G4-A-1321 — готовый отчёт с решением «נדרש בירור נוסף». Только чтение — @prod-safe.
import * as path from 'path';
import { test, expect } from '@playwright/test';
import { candidateRows, decisionCell, rowsByName, EMPTY_RESULT } from './support';

test.use({ storageState: path.resolve(__dirname, '../../../auth/business.json') });

const CANDIDATE = 'QA-G4-A-1321';

test.describe('Дашборд — ссылка «לכל הדוחות המוכנים» (#a8e7e24c31c0c182cdc6043e)', () => {
  test('готовый отчёт с решением не попадает в набор ссылки @desktop @prod-safe #a8e7e24c31c0c182cdc6043e', async ({ page }) => {
    // Источник: SPEC #027719 п.32 — «מוכן» = все готовые отчёты, в т.ч. с решением.
    await page.goto(`/candidates?status=ready&q=${encodeURIComponent(CANDIDATE)}`);
    const row = rowsByName(page, CANDIDATE);
    await expect(row).toHaveCount(1);
    await expect(decisionCell(page, row)).toHaveText('נדרש בירור נוסף');

    // Источник: AC — набор ссылки = готовые без החלטת גיוס.
    await page.goto(`/candidates?status=awaiting_decision&q=${encodeURIComponent(CANDIDATE)}`);
    await expect(page.getByText(EMPTY_RESULT)).toBeVisible();
    await expect(page.getByText('מציג 0 מתוך 0', { exact: true })).toBeVisible();
    await expect(candidateRows(page)).toHaveCount(0);
  });
});
